(async()=>{const E=window.__echoes;
 const seen=new Set(); const log=[];
 const collect=()=>{for(const e of E.events){ if(!seen.has(e)){seen.add(e); if(/boss_|room_cleared|run_end|spawn_telegraph|enemy_spawn/.test(e.type)) log.push(e);} }};
 E.cmd('skipToRoom',8); await new Promise(r=>setTimeout(r,600));
 const hp=[]; const t0=Date.now();
 while(Date.now()-t0<170000){
   collect();
   const v=E.cmd('runState');
   if(v.phase!=='combat') break;
   const b=v.boss; if(b) hp.push([E.tick, b.hp, b.adds, b.sealed?1:0, b.phasesFired]);
   E.cmd('killAllEnemies');
   await new Promise(r=>setTimeout(r,250));
 }
 collect();
 const v=E.cmd('runState');
 const phases=log.filter(e=>/phase|add/.test(e.type)).map(e=>e.tick+':'+e.type+':'+JSON.stringify(e));
 const kinds={}; for(const e of log) kinds[e.type]=(kinds[e.type]||0)+1;
 return {phase:v.phase, room:v.room, summary:v.summary, kinds, phases:phases.slice(0,20),
   hpSample:hp.filter((r,i)=>i%4===0).slice(0,40), lastEvents:log.slice(-14).map(e=>e.tick+':'+e.type+':'+JSON.stringify(e).slice(0,160))};})()
